<script lang="ts">
 import {RHYTHM_KEYS,rhythmLaneForKey} from '../../../lib/rhythmChart';
 let {notes,elapsed,fallMs=1650,playing=false,finished=false,score=0,combo=0,judge='',onhit,onstart,onpause}:{notes:{track:number;hitAt:number;judged:boolean}[];elapsed:number;fallMs?:number;playing?:boolean;finished?:boolean;score?:number;combo?:number;judge?:string;onhit:(lane:number)=>void;onstart:()=>void;onpause:()=>void}=$props();
 const colors=['#85c8e3','#a9b7ee','#e6c78d','#b7a4dc','#86c9ba'];
 let flashes=$state([0,0,0,0,0]);
 const duration=$derived((notes.slice(-1)[0]?.hitAt??1)+400);
 function hit(lane:number){if(!playing||finished)return;flashes[lane]=performance.now();onhit(lane);}
 function keyboard(e:KeyboardEvent){if(e.repeat||!playing||e.target instanceof HTMLInputElement||e.target instanceof HTMLTextAreaElement)return;const lane=rhythmLaneForKey(e.code);if(lane!==undefined){e.preventDefault();hit(lane);}}
</script>
<svelte:window onkeydown={keyboard}/>
<section class="five-lane" aria-label="五轨节奏游戏" data-no-drag-scroll>
 <div class="scorebar"><span>ACCURACY <b>{Math.round(score)}<small> 分</small></b></span><span class="combo">{combo}<small> COMBO</small></span><button onclick={onpause} disabled={!playing}>暂停</button></div>
 <div class="track-frame"><div class="track-grid">
   {#each colors as color,lane}<button class="lane" style={`--lane:${color}`} class:lit={playing&&performance.now()-flashes[lane]<120} aria-label={`第 ${lane+1} 轨，${RHYTHM_KEYS[lane]}`} tabindex="-1" onpointerdown={e=>{e.preventDefault();hit(lane);}} onclick={e=>{if(e.detail===0)hit(lane);}}>
     {#each notes as note,i (i)}{#if note.track===lane&&!note.judged&&note.hitAt-elapsed<fallMs+100&&note.hitAt-elapsed> -350}<span class="note" style={`top:${78-(note.hitAt-elapsed)/fallMs*78}%`}></span>{/if}{/each}
     <span class="judgment-line"></span><span class="key"><b>{RHYTHM_KEYS[lane]}</b><small>{lane+1}</small></span>
   </button>{/each}
  </div><div class="judgment" aria-live="off">{judge}</div>
  {#if !playing}<div class="intro"><small>FIVE KEYS / 五轨节奏</small><h2>{finished?'曲目完成':elapsed?'节奏已暂停':'跟上这一拍'}</h2><p>音符落到横线时按下对应轨道<br/>双键一起按，空拍留给下一句</p>{#if !finished}<button onclick={onstart}>{elapsed?'继续演奏':'开始曲目'}</button>{/if}</div>{/if}
 </div>
 <div class="progress" role="progressbar" aria-label="曲目进度" aria-valuenow={Math.round(elapsed/duration*100)} aria-valuemin="0" aria-valuemax="100"><span style={`width:${Math.min(100,elapsed/duration*100)}%`}></span></div>
 <p class="help">D · F · 空格 · J · K <span>也可使用 1—5，或直接点击轨道</span></p>
</section>
<style>
 .five-lane{height:100%;min-height:0;flex:1;display:flex;flex-direction:column;gap:8px;box-sizing:border-box;background:#111827;color:#d9e3f2;padding:clamp(8px,1.5vh,16px) max(12px,env(safe-area-inset-right)) max(6px,env(safe-area-inset-bottom));font-family:system-ui,'Microsoft YaHei',sans-serif}.scorebar{display:flex;align-items:center;justify-content:space-between;gap:12px;width:min(820px,100%);margin:auto;font-size:9px;letter-spacing:1.5px;color:#8e9db5}.scorebar>span:first-child{display:flex;align-items:center;gap:12px}.scorebar b{font-size:24px;font-variant-numeric:tabular-nums;font-weight:500;letter-spacing:0;color:#e5cc9c}.scorebar small{font-size:10px;font-weight:400;color:#9baac2}.combo{font:500 25px ui-monospace,monospace;color:#bdcde4;white-space:nowrap}.scorebar button{border:1px solid #4c5871;background:#1d293d;border-radius:6px;color:#cbd6e6;min-height:32px;padding:4px 14px;cursor:pointer}.scorebar button:disabled{opacity:.4}.track-frame{position:relative;flex:1;min-height:140px;width:min(820px,100%);margin:auto;overflow:hidden;border:1px solid #4c5871;border-radius:8px;background:linear-gradient(#131c2d,#1b263b);box-shadow:inset 0 20px 40px #0003}.track-grid{position:absolute;inset:0;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:1px;background:#46516b40}.lane{position:relative;display:block;overflow:hidden;border:0;padding:0;background:linear-gradient(#172133,#202c43);border-radius:0;touch-action:none;user-select:none;cursor:pointer;color:var(--lane)}.lane:nth-child(3){background:linear-gradient(#1e2739,#2a3349)}.lane.lit,.lane:active{background:linear-gradient(#26334b,color-mix(in srgb,var(--lane) 30%,#172337))}.note{position:absolute;left:9%;width:82%;height:clamp(10px,1.9vh,15px);transform:translateY(-50%);border-radius:3px;background:var(--lane);box-shadow:0 0 10px color-mix(in srgb,var(--lane) 25%,transparent),inset 0 2px 0 #ffffff88;pointer-events:none}.judgment-line{position:absolute;top:78%;left:0;width:100%;height:3px;background:#e7d5b2;box-shadow:0 0 15px #dfbe6955;pointer-events:none}.key{position:absolute;top:83%;left:0;right:0;display:flex;align-items:center;justify-content:center;gap:8px;pointer-events:none}.key b{font-size:clamp(13px,2.2vh,22px);font-weight:500}.key small{font-size:10px;opacity:.5}.judgment{position:absolute;top:40%;left:0;right:0;text-align:center;font-size:clamp(16px,3vh,24px);font-weight:600;letter-spacing:3px;color:#eee0bf;pointer-events:none;text-shadow:0 2px 8px #000}.intro{position:absolute;inset:0;background:#111a2cde;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:12px;padding:12px}.intro>small{font-size:9px;letter-spacing:3px;color:#9caec9}.intro h2{margin:0;font-size:clamp(20px,4vh,30px);font-weight:500;letter-spacing:3px}.intro p{font-size:12px;line-height:1.8;color:#9baec9;margin:0}.intro button{background:#ddc496;color:#1e2c43;border:1px solid #f1dfb9;padding:10px 30px;border-radius:6px;font:600 13px system-ui;min-height:42px;cursor:pointer}.progress{height:3px;background:#364157;width:min(820px,100%);margin:auto;border-radius:3px;overflow:hidden}.progress span{display:block;height:100%;background:#d5bd8e}.help{width:min(820px,100%);margin:0 auto;font-size:10px;color:#a4b4ce;text-align:center;line-height:1.6}.help span{margin-left:14px;color:#7889a6}@media(max-height:480px){.five-lane{gap:5px;padding-top:5px}.scorebar b,.combo{font-size:18px}.intro{gap:7px}.intro p{font-size:10px}.intro button{min-height:34px;padding:6px 22px}.help{font-size:9px}.track-frame{min-height:100px}}@media(max-width:480px){.help span{display:block;margin:0}.key{gap:4px}.scorebar{letter-spacing:.4px}.track-frame{min-height:200px}}
</style>
